/**
 * @brief Function to initialize the EVADC module as per the configuration made in the GUI.
 * @param handle Pointer to static content of APP configuration.
 * @return ANALOG_CONVERTER_EVADC_STATUS_t: Status of the ANALOG_CONVERTER_EVADC driver initialization.\n
 *   @ref ANALOG_CONVERTER_EVADC_STATUS_SUCCESS - on successful initialization.\n
 *   @ref ANALOG_CONVERTER_EVADC_STATUS_FAILURE - if initialization fails.\n
 * \par<b>Example Usage</b><br>
 * @code
 * #include "Ifx_Types.h"
 * #include "IfxCpu.h"
 * #include "IfxScuWdt.h"
 * #include "DAVE.h"
 * 
 * IFX_ALIGN(4) IfxCpu_syncEvent g_cpuSyncEvent = 0;
 * 
 * void core0_main(void)
 * {
 *   IfxCpu_enableInterrupts();
 *   IfxScuWdt_disableCpuWatchdog(IfxScuWdt_getCpuWatchdogPassword());
 *   IfxScuWdt_disableSafetyWatchdog(IfxScuWdt_getSafetyWatchdogPassword());
 *   IfxCpu_emitEvent(&g_cpuSyncEvent);
 *   IfxCpu_waitEvent(&g_cpuSyncEvent, 1);
 * 
 *   ANALOG_CONVERTER_EVADC_STATUS_t status = ANALOG_CONVERTER_EVADC_Init(&ANALOG_CONVERTER_EVADC_0);     // Initialization of APP
 *   if (status != ANALOG_CONVERTER_EVADC_STATUS_SUCCESS) {
 *     while (1) {
 *       // Implement your code to handle the error here!
 *     }
 *   }
 * 
 *   while (1);
 * }
 * @endcode
 * @note Normally this will be called automatically from DAVE_Init() that are located in core0_main().
 */
ANALOG_CONVERTER_EVADC_STATUS_t ANALOG_CONVERTER_EVADC_Init(ANALOG_CONVERTER_EVADC_t *handle);

/**
 * @brief Start conversion of a given group and its channels.
 * @param handle Pointer to static content of APP configuration.
 * @return ANALOG_CONVERTER_EVADC_STATUS_t: Status of the ANALOG_CONVERTER_EVADC driver operation.\n
 *   @ref ANALOG_CONVERTER_EVADC_STATUS_SUCCESS - on successful operation.\n
 *   @ref ANALOG_CONVERTER_EVADC_STATUS_FAILURE - if operation fails.\n
 *
 * \par<b>Example Usage</b><br>
 * @code
 * #include "Ifx_Types.h"
 * #include "IfxCpu.h"
 * #include "IfxScuWdt.h"
 * #include "DAVE.h"
 * 
 * IFX_ALIGN(4) IfxCpu_syncEvent g_cpuSyncEvent = 0;
 * 
 * void core0_main(void)
 * {
 *   IfxCpu_enableInterrupts();
 *   IfxScuWdt_disableCpuWatchdog(IfxScuWdt_getCpuWatchdogPassword());
 *   IfxScuWdt_disableSafetyWatchdog(IfxScuWdt_getSafetyWatchdogPassword());
 *   IfxCpu_emitEvent(&g_cpuSyncEvent);
 *   IfxCpu_waitEvent(&g_cpuSyncEvent, 1);
 * 
 *   DAVE_STATUS_t status = DAVE_Init();           // Initialization of DAVE APPs
 *   if (status != DAVE_STATUS_SUCCESS) {
 *     while (1) {
 *       // Implement your code to handle the error here!
 *     }
 *   }
 * 
 *   // Start conversion of enabled channels of APP instance
 *   ANALOG_CONVERTER_EVADC_StartConversion(&ANALOG_CONVERTER_EVADC_0);
 * 
 *   while (1);
 * }
 * @endcode
 * @note This function must be called before getting trigger to start conversion, even if the "External Trigger" is selected.
 *       Because addition of channels to be converted to queue is needed before get triggered.
 *       Only when the "External Trigger" is not used, this function also put a software trigger to start conversion as well.
 */
ANALOG_CONVERTER_EVADC_STATUS_t ANALOG_CONVERTER_EVADC_StartConversion(ANALOG_CONVERTER_EVADC_t *handle);

/**
 * @brief Capture conversion results of a group into designated result buffer
 * @param handle Pointer to static content of APP configuration.
 * @return ANALOG_CONVERTER_EVADC_STATUS_t: Status of the ANALOG_CONVERTER_EVADC driver operation.\n
 *   @ref ANALOG_CONVERTER_EVADC_STATUS_SUCCESS - on successful operation.\n
 *   @ref ANALOG_CONVERTER_EVADC_STATUS_FAILURE - if operation fails.\n
 *
 * \par<b>Example Usage</b><br>
 * @code
 * #include "Ifx_Types.h"
 * #include "IfxCpu.h"
 * #include "IfxScuWdt.h"
 * #include "DAVE.h"
 * 
 * IFX_ALIGN(4) IfxCpu_syncEvent g_cpuSyncEvent = 0;
 * 
 * void core0_main(void)
 * {
 *   IfxCpu_enableInterrupts();
 *   IfxScuWdt_disableCpuWatchdog(IfxScuWdt_getCpuWatchdogPassword());
 *   IfxScuWdt_disableSafetyWatchdog(IfxScuWdt_getSafetyWatchdogPassword());
 *   IfxCpu_emitEvent(&g_cpuSyncEvent);
 *   IfxCpu_waitEvent(&g_cpuSyncEvent, 1);
 * 
 *   DAVE_STATUS_t status = DAVE_Init();           // Initialization of DAVE APPs
 *   if (status != DAVE_STATUS_SUCCESS) {
 *     while (1) {
 *       // Implement your code to handle the error here!
 *     }
 *   }
 * 
 *   // Start conversion of enabled channels of APP instance
 *   ANALOG_CONVERTER_EVADC_StartConversion(&ANALOG_CONVERTER_EVADC_0);
 * 
 *   // Capture results into the array defined in the APP handle
 *   if (ANALOG_CONVERTER_EVADC_CaptureResults(&ANALOG_CONVERTER_EVADC_0) == ANALOG_CONVERTER_EVADC_STATUS_SUCCESS)
 *   {
 *     // The result of the conversion is stored in the APP handle.
 *     // The converted digital value can be read as follows
 *     uint32 result = ANALOG_CONVERTER_EVADC_GetChannelResultU32(&ANALOG_CONVERTER_EVADC_0, ANALOG_CONVERTER_EVADC_0_ADC_CHANNEL_0);
 *   }
 * 
 *   while (1);
 * }
 * @endcode
 * @note If conversion results of configured channels are not ready to read, the return code becomes ANALOG_CONVERTER_EVADC_STATUS_FAILURE.
 */
ANALOG_CONVERTER_EVADC_STATUS_t ANALOG_CONVERTER_EVADC_CaptureResults(ANALOG_CONVERTER_EVADC_t *handle);

/**
 * @brief Capture conversion result of a single channel of a group into designated result buffer.
 * @param handle Pointer to static content of APP configuration.
 * @param channel_index Channel index number
 * @return ANALOG_CONVERTER_EVADC_STATUS_t: Status of the ANALOG_CONVERTER_EVADC driver operation.\n
 *   @ref ANALOG_CONVERTER_EVADC_STATUS_SUCCESS - on successful operation.\n
 *   @ref ANALOG_CONVERTER_EVADC_STATUS_FAILURE - if operation fails.\n
 *
 * \par<b>Example Usage</b><br>
 * @code
 * #include "Ifx_Types.h"
 * #include "IfxCpu.h"
 * #include "IfxScuWdt.h"
 * #include "DAVE.h"
 * 
 * IFX_ALIGN(4) IfxCpu_syncEvent g_cpuSyncEvent = 0;
 * 
 * void core0_main(void)
 * {
 *   IfxCpu_enableInterrupts();
 *   IfxScuWdt_disableCpuWatchdog(IfxScuWdt_getCpuWatchdogPassword());
 *   IfxScuWdt_disableSafetyWatchdog(IfxScuWdt_getSafetyWatchdogPassword());
 *   IfxCpu_emitEvent(&g_cpuSyncEvent);
 *   IfxCpu_waitEvent(&g_cpuSyncEvent, 1);
 * 
 *   DAVE_STATUS_t status = DAVE_Init();           // Initialization of DAVE APPs
 *   if (status != DAVE_STATUS_SUCCESS) {
 *     while (1) {
 *       // Implement your code to handle the error here!
 *     }
 *   }
 * 
 *   // Start conversion of enabled channels of APP instance
 *   ANALOG_CONVERTER_EVADC_StartConversion(&ANALOG_CONVERTER_EVADC_0);
 * 
 *   // Read result array
 *   if (ANALOG_CONVERTER_EVADC_CaptureResult(&ANALOG_CONVERTER_EVADC_0, ANALOG_CONVERTER_EVADC_0_ADC_CHANNEL_0) == ANALOG_CONVERTER_EVADC_STATUS_SUCCESS)
 *   {
 *     // The result of the conversion is stored in the APP handle.
 *     // The converted digital value can be read as follows
 *     uint32 result = ANALOG_CONVERTER_EVADC_GetChannelResultU32(&ANALOG_CONVERTER_EVADC_0, ANALOG_CONVERTER_EVADC_0_ADC_CHANNEL_0);
 *   }
 * 
 *   while (1);
 * }
 * @endcode
 * @note If conversion result of specified channel is not ready to read, the return code becomes ANALOG_CONVERTER_EVADC_STATUS_FAILURE.
 */
ANALOG_CONVERTER_EVADC_STATUS_t ANALOG_CONVERTER_EVADC_CaptureResult(ANALOG_CONVERTER_EVADC_t *handle, int channel_index);

/**
 * @brief Read conversion results for a single channel of an APP instance
 * The requested channel can be accessed by defined custom name in the APP GUI.
 * This name will be prefixed by APP's instance name.
 * @param handle Pointer to static content of APP configuration.
 * @param channel_index Channel index number
 * @return void
 *
 * \par<b>Example Usage</b><br>
 * @code
 * #include "Ifx_Types.h"
 * #include "IfxCpu.h"
 * #include "IfxScuWdt.h"
 * #include "DAVE.h"
 * 
 * IFX_ALIGN(4) IfxCpu_syncEvent g_cpuSyncEvent = 0;
 * 
 * void core0_main(void)
 * {
 *   IfxCpu_enableInterrupts();
 *   IfxScuWdt_disableCpuWatchdog(IfxScuWdt_getCpuWatchdogPassword());
 *   IfxScuWdt_disableSafetyWatchdog(IfxScuWdt_getSafetyWatchdogPassword());
 *   IfxCpu_emitEvent(&g_cpuSyncEvent);
 *   IfxCpu_waitEvent(&g_cpuSyncEvent, 1);
 * 
 *   DAVE_STATUS_t status = DAVE_Init();           // Initialization of DAVE APPs
 *   if (status != DAVE_STATUS_SUCCESS) {
 *     while (1) {
 *       // Implement your code to handle the error here!
 *     }
 *   }
 * 
 *   // Start conversion of enabled channels of APP instance
 *   ANALOG_CONVERTER_EVADC_StartConversion(&ANALOG_CONVERTER_EVADC_0);
 * 
 *   // Capture results into predefined global variable for APP instance
 *   ANALOG_CONVERTER_EVADC_CaptureResults(&ANALOG_CONVERTER_EVADC_0);
 * 
 *   // Get conversion value
 *   uint32 adcValue = ANALOG_CONVERTER_EVADC_GetChannelResultU32(&ANALOG_CONVERTER_EVADC_0, ANALOG_CONVERTER_EVADC_0_ADC_CHANNEL_0);
 * 
 *   while (1);
 * }
 * @endcode
 */
uint32 ANALOG_CONVERTER_EVADC_GetChannelResultU32(ANALOG_CONVERTER_EVADC_t *handle, int channel_index);

